function validate([prices]) {
  if (!Array.isArray(prices) || prices.length < 1 || prices.length > 100000) return 'prices needs 1 to 10^5 values.';
  if (prices.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each price is an integer from 1 to 10^5.';
  return null;
}

