function getDescentPeriods(prices) {
  let run = 1;
  let total = 1;
  for (let i = 1; i < prices.length; i++) {
    if (prices[i - 1] - prices[i] === 1) {
      run++;
    } else {
      run = 1;
    }
    total += run;
  }
  return total;
}

