function getDescentPeriods(prices) {
  let count = 0;
  for (let start = 0; start < prices.length; start++) {
    for (let end = start; end < prices.length; end++) {
      let ok = true;
      for (let k = start + 1; k <= end; k++) if (prices[k] !== prices[k - 1] - 1) ok = false;
      if (ok) count++;
    }
  }
  return count;
}

