function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 9);
  const prices = [];
  let value = 1 + Math.floor(rand() * (size === 'large' ? 100000 : 8));
  for (let i = 0; i < n; i++) {
    prices.push(value);
    const r = rand();
    if (r < 0.6 && value > 1) value -= 1;
    else if (size === 'large') value = 1 + Math.floor(rand() * 100000);
    else value = 1 + Math.floor(rand() * 8);
  }
  return [prices];
}
